mapper.select:
SELECT * FROM t_spd_purchase WHERE del_flag = #{delFlag}

    AND purchase_no LIKE CONCAT('%', #{query.purchaseNo}, '%')


    AND supplier_id = #{query.supplierId}


    AND warehouse_id = #{query.warehouseId}


    AND purchase_status = #{query.purchaseStatus}


    AND create_time >= #{query.createTimeStart}


    AND create_time <= #{query.createTimeEnd}

ORDER BY create_time DESC
